namespace BrewNest.Modules.Catalog.Application.Services;

internal enum CatalogResultStatus { Success, Validation, NotFound, Conflict }
internal sealed record CatalogResult<T>(CatalogResultStatus Status, T? Value, string[] Errors)
{
    public bool Succeeded => Status == CatalogResultStatus.Success;
    public static CatalogResult<T> Success(T value) => new(CatalogResultStatus.Success, value, []);
    public static CatalogResult<T> Failure(CatalogResultStatus status, params string[] errors) => new(status, default, errors);
}
internal sealed record CatalogRequestContext(string Actor)
{
    public static CatalogRequestContext FromHttpContext(HttpContext context) => new(context.User.FindFirstValue(ClaimTypes.NameIdentifier) ?? context.User.Identity?.Name ?? "anonymous");
}

internal sealed class CatalogService(CatalogDbContext dbContext, TimeProvider timeProvider)
{
    private DateTimeOffset Now => timeProvider.GetUtcNow();

    public async Task<CatalogResult<UnitOfMeasureResponse[]>> GetUnitsAsync(CancellationToken token) => CatalogResult<UnitOfMeasureResponse[]>.Success((await dbContext.UnitsOfMeasure.AsNoTracking().OrderBy(x => x.Code).ToArrayAsync(token)).Select(Map).ToArray());
    public async Task<CatalogResult<UnitOfMeasureResponse>> CreateUnitAsync(CreateUnitOfMeasureRequest request, CatalogRequestContext context, CancellationToken token)
    {
        var errors = ValidateUnit(request.Code, request.Name, request.Symbol, request.Category, request.DecimalPlaces);
        if (errors.Length > 0) return Validation<UnitOfMeasureResponse>(errors);
        if (await CodeExistsAsync(dbContext.UnitsOfMeasure, request.Code, null, token)) return Conflict<UnitOfMeasureResponse>("The unit code already exists.");
        var entity = New<UnitOfMeasure>(context); entity.Code = Code(request.Code); entity.Name = request.Name.Trim(); entity.Symbol = request.Symbol.Trim(); entity.Category = request.Category.Trim(); entity.DecimalPlaces = request.DecimalPlaces; dbContext.UnitsOfMeasure.Add(entity); AddStatus(entity, "Created", context);
        return await SaveAsync(() => Map(entity), token);
    }
    public async Task<CatalogResult<UnitOfMeasureResponse>> UpdateUnitAsync(Guid id, UpdateUnitOfMeasureRequest request, CatalogRequestContext context, CancellationToken token)
    {
        var entity = await dbContext.UnitsOfMeasure.SingleOrDefaultAsync(x => x.Id == id, token); if (entity is null) return NotFound<UnitOfMeasureResponse>();
        var errors = ValidateUnit(request.Code, request.Name, request.Symbol, request.Category, request.DecimalPlaces); if (errors.Length > 0) return Validation<UnitOfMeasureResponse>(errors);
        if (!ApplyVersion(entity, request.Version)) return VersionFailure<UnitOfMeasureResponse>(); if (await CodeExistsAsync(dbContext.UnitsOfMeasure, request.Code, id, token)) return Conflict<UnitOfMeasureResponse>("The unit code already exists.");
        UpdateStatus(entity, request.IsActive, request.Reason, context); entity.Code = Code(request.Code); entity.Name = request.Name.Trim(); entity.Symbol = request.Symbol.Trim(); entity.Category = request.Category.Trim(); entity.DecimalPlaces = request.DecimalPlaces; Touch(entity, context); return await SaveAsync(() => Map(entity), token);
    }

    public async Task<CatalogResult<ItemGroupResponse[]>> GetGroupsAsync(CancellationToken token) => CatalogResult<ItemGroupResponse[]>.Success((await dbContext.ItemGroups.AsNoTracking().OrderBy(x => x.Code).ToArrayAsync(token)).Select(Map).ToArray());
    public async Task<CatalogResult<ItemGroupResponse>> CreateGroupAsync(CreateItemGroupRequest request, CatalogRequestContext context, CancellationToken token)
    {
        var errors = ValidateCodeName(request.Code, request.Name); if (!ParseOptionalItemType(request.AppliesTo, out var appliesTo)) errors = errors.Append("AppliesTo must be blank, MenuItem, RawMaterial, or PackagingMaterial.").ToArray(); if (errors.Length > 0) return Validation<ItemGroupResponse>(errors);
        if (await CodeExistsAsync(dbContext.ItemGroups, request.Code, null, token)) return Conflict<ItemGroupResponse>("The item-group code already exists.");
        var entity = New<ItemGroup>(context); entity.Code = Code(request.Code); entity.Name = request.Name.Trim(); entity.AppliesTo = appliesTo; entity.RequiresInspection = request.RequiresInspection; dbContext.ItemGroups.Add(entity); AddStatus(entity, "Created", context); return await SaveAsync(() => Map(entity), token);
    }
    public async Task<CatalogResult<ItemGroupResponse>> UpdateGroupAsync(Guid id, UpdateItemGroupRequest request, CatalogRequestContext context, CancellationToken token)
    {
        var entity = await dbContext.ItemGroups.SingleOrDefaultAsync(x => x.Id == id, token); if (entity is null) return NotFound<ItemGroupResponse>(); var errors = ValidateCodeName(request.Code, request.Name); if (!ParseOptionalItemType(request.AppliesTo, out var appliesTo)) errors = errors.Append("AppliesTo is invalid.").ToArray(); if (errors.Length > 0) return Validation<ItemGroupResponse>(errors); if (!ApplyVersion(entity, request.Version)) return VersionFailure<ItemGroupResponse>(); if (await CodeExistsAsync(dbContext.ItemGroups, request.Code, id, token)) return Conflict<ItemGroupResponse>("The item-group code already exists."); UpdateStatus(entity, request.IsActive, request.Reason, context); entity.Code = Code(request.Code); entity.Name = request.Name.Trim(); entity.AppliesTo = appliesTo; entity.RequiresInspection = request.RequiresInspection; Touch(entity, context); return await SaveAsync(() => Map(entity), token);
    }

    public async Task<CatalogResult<CatalogItemResponse[]>> GetItemsAsync(string? itemType, CancellationToken token)
    {
        var query = dbContext.Items.AsNoTracking(); if (!string.IsNullOrWhiteSpace(itemType)) { if (!Enum.TryParse<CatalogItemType>(itemType, true, out var parsed) || !Enum.IsDefined(parsed)) return Validation<CatalogItemResponse[]>("Item type is invalid."); query = query.Where(x => x.ItemType == parsed); }
        return CatalogResult<CatalogItemResponse[]>.Success((await query.OrderBy(x => x.Code).ToArrayAsync(token)).Select(Map).ToArray());
    }
    public async Task<CatalogResult<CatalogItemResponse>> CreateItemAsync(CreateCatalogItemRequest request, CatalogRequestContext context, CancellationToken token)
    {
        var errors = ValidateItem(request.Code, request.Name, request.ItemType, request.SalesPrice, request.StandardCost, request.ShelfLifeDays, out var itemType); if (errors.Length > 0) return Validation<CatalogItemResponse>(errors); var referenceError = await ValidateItemReferencesAsync(request.UnitOfMeasureId, request.ItemGroupId, itemType, token); if (referenceError is not null) return Validation<CatalogItemResponse>(referenceError); if (await CodeExistsAsync(dbContext.Items, request.Code, null, token)) return Conflict<CatalogItemResponse>("The item code already exists.");
        var entity = New<CatalogItem>(context); entity.Code = Code(request.Code); entity.Name = request.Name.Trim(); entity.Description = request.Description.Trim(); entity.ItemType = itemType; entity.UnitOfMeasureId = request.UnitOfMeasureId; entity.ItemGroupId = request.ItemGroupId; entity.SalesPrice = request.SalesPrice; entity.StandardCost = request.StandardCost; entity.ShelfLifeDays = request.ShelfLifeDays; entity.RequiresInspection = request.RequiresInspection; dbContext.Items.Add(entity); AddStatus(entity, "Created", context); return await SaveAsync(() => Map(entity), token);
    }
    public async Task<CatalogResult<CatalogItemResponse>> UpdateItemAsync(Guid id, UpdateCatalogItemRequest request, CatalogRequestContext context, CancellationToken token)
    {
        var entity = await dbContext.Items.SingleOrDefaultAsync(x => x.Id == id, token); if (entity is null) return NotFound<CatalogItemResponse>(); var errors = ValidateItem(request.Code, request.Name, entity.ItemType.ToString(), request.SalesPrice, request.StandardCost, request.ShelfLifeDays, out _); if (errors.Length > 0) return Validation<CatalogItemResponse>(errors); var referenceError = await ValidateItemReferencesAsync(request.UnitOfMeasureId, request.ItemGroupId, entity.ItemType, token); if (referenceError is not null) return Validation<CatalogItemResponse>(referenceError); if (!ApplyVersion(entity, request.Version)) return VersionFailure<CatalogItemResponse>(); if (await CodeExistsAsync(dbContext.Items, request.Code, id, token)) return Conflict<CatalogItemResponse>("The item code already exists."); UpdateStatus(entity, request.IsActive, request.Reason, context); entity.Code = Code(request.Code); entity.Name = request.Name.Trim(); entity.Description = request.Description.Trim(); entity.UnitOfMeasureId = request.UnitOfMeasureId; entity.ItemGroupId = request.ItemGroupId; entity.SalesPrice = request.SalesPrice; entity.StandardCost = request.StandardCost; entity.ShelfLifeDays = request.ShelfLifeDays; entity.RequiresInspection = request.RequiresInspection; Touch(entity, context); return await SaveAsync(() => Map(entity), token);
    }

    public async Task<CatalogResult<CustomerResponse[]>> GetCustomersAsync(CancellationToken token) => CatalogResult<CustomerResponse[]>.Success((await dbContext.Customers.AsNoTracking().OrderBy(x => x.Code).ToArrayAsync(token)).Select(Map).ToArray());
    public async Task<CatalogResult<CustomerResponse>> CreateCustomerAsync(CreateCustomerRequest request, CatalogRequestContext context, CancellationToken token) { var errors = ValidateParty(request.Code, request.Name, request.Email, request.Phone); if (errors.Length > 0) return Validation<CustomerResponse>(errors); if (await CodeExistsAsync(dbContext.Customers, request.Code, null, token)) return Conflict<CustomerResponse>("The customer code already exists."); var entity = New<Customer>(context); entity.Code=Code(request.Code); entity.Name=request.Name.Trim(); entity.Phone=request.Phone.Trim(); entity.Email=request.Email.Trim(); entity.Address=request.Address.Trim(); dbContext.Customers.Add(entity); AddStatus(entity,"Created",context); return await SaveAsync(()=>Map(entity),token); }
    public async Task<CatalogResult<CustomerResponse>> UpdateCustomerAsync(Guid id, UpdateCustomerRequest request, CatalogRequestContext context, CancellationToken token) { var entity=await dbContext.Customers.SingleOrDefaultAsync(x=>x.Id==id,token); if(entity is null)return NotFound<CustomerResponse>(); var errors=ValidateParty(request.Code,request.Name,request.Email,request.Phone);if(errors.Length>0)return Validation<CustomerResponse>(errors);if(!ApplyVersion(entity,request.Version))return VersionFailure<CustomerResponse>();if(await CodeExistsAsync(dbContext.Customers,request.Code,id,token))return Conflict<CustomerResponse>("The customer code already exists.");UpdateStatus(entity,request.IsActive,request.Reason,context);entity.Code=Code(request.Code);entity.Name=request.Name.Trim();entity.Phone=request.Phone.Trim();entity.Email=request.Email.Trim();entity.Address=request.Address.Trim();Touch(entity,context);return await SaveAsync(()=>Map(entity),token); }

