    public async Task<CatalogResult<VendorResponse>> CreateVendorAsync(CreateVendorRequest request, CatalogRequestContext context, CancellationToken token) { var errors=ValidateParty(request.Code,request.Name,request.Email,request.Phone);if(errors.Length>0)return Validation<VendorResponse>(errors);if(await CodeExistsAsync(dbContext.Vendors,request.Code,null,token))return Conflict<VendorResponse>("The vendor code already exists.");var entity=New<Vendor>(context);SetVendor(entity,request.Code,request.Name,request.ContactPerson,request.Phone,request.Email,request.Address,request.TaxRegistrationNumber);dbContext.Vendors.Add(entity);AddStatus(entity,"Created",context);return await SaveAsync(()=>Map(entity),token); }
    public async Task<CatalogResult<VendorResponse>> UpdateVendorAsync(Guid id, UpdateVendorRequest request, CatalogRequestContext context, CancellationToken token) { var entity=await dbContext.Vendors.SingleOrDefaultAsync(x=>x.Id==id,token);if(entity is null)return NotFound<VendorResponse>();var errors=ValidateParty(request.Code,request.Name,request.Email,request.Phone);if(errors.Length>0)return Validation<VendorResponse>(errors);if(!ApplyVersion(entity,request.Version))return VersionFailure<VendorResponse>();if(await CodeExistsAsync(dbContext.Vendors,request.Code,id,token))return Conflict<VendorResponse>("The vendor code already exists.");UpdateStatus(entity,request.IsActive,request.Reason,context);SetVendor(entity,request.Code,request.Name,request.ContactPerson,request.Phone,request.Email,request.Address,request.TaxRegistrationNumber);Touch(entity,context);return await SaveAsync(()=>Map(entity),token); }

    public async Task<CatalogResult<DiningTableResponse[]>> GetTablesAsync(CancellationToken token) => CatalogResult<DiningTableResponse[]>.Success((await dbContext.DiningTables.AsNoTracking().OrderBy(x => x.Code).ToArrayAsync(token)).Select(Map).ToArray());
    public async Task<CatalogResult<DiningTableResponse>> CreateTableAsync(CreateDiningTableRequest request,CatalogRequestContext context,CancellationToken token){var errors=ValidateCodeName(request.Code,request.Name).Concat(request.Capacity<1?["Capacity must be positive."]:[]).ToArray();if(errors.Length>0)return Validation<DiningTableResponse>(errors);if(await CodeExistsAsync(dbContext.DiningTables,request.Code,null,token))return Conflict<DiningTableResponse>("The table code already exists.");var entity=New<DiningTable>(context);entity.Code=Code(request.Code);entity.Name=request.Name.Trim();entity.Capacity=request.Capacity;entity.Area=request.Area.Trim();dbContext.DiningTables.Add(entity);AddStatus(entity,"Created",context);return await SaveAsync(()=>Map(entity),token);}
    public async Task<CatalogResult<DiningTableResponse>> UpdateTableAsync(Guid id,UpdateDiningTableRequest request,CatalogRequestContext context,CancellationToken token){var entity=await dbContext.DiningTables.SingleOrDefaultAsync(x=>x.Id==id,token);if(entity is null)return NotFound<DiningTableResponse>();var errors=ValidateCodeName(request.Code,request.Name).Concat(request.Capacity<1?["Capacity must be positive."]:[]).ToArray();if(errors.Length>0)return Validation<DiningTableResponse>(errors);if(!ApplyVersion(entity,request.Version))return VersionFailure<DiningTableResponse>();if(await CodeExistsAsync(dbContext.DiningTables,request.Code,id,token))return Conflict<DiningTableResponse>("The table code already exists.");UpdateStatus(entity,request.IsActive,request.Reason,context);entity.Code=Code(request.Code);entity.Name=request.Name.Trim();entity.Capacity=request.Capacity;entity.Area=request.Area.Trim();Touch(entity,context);return await SaveAsync(()=>Map(entity),token);}

    public async Task<CatalogResult<WarehouseResponse[]>> GetWarehousesAsync(CancellationToken token)=>CatalogResult<WarehouseResponse[]>.Success((await dbContext.Warehouses.AsNoTracking().OrderBy(x=>x.Code).ToArrayAsync(token)).Select(Map).ToArray());
